import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>Fotoğrafınızın pikselleri doğru, boyutu doğru ve görünümü doğru ama matbaa ya da yayın platformu onu reddediyor. Neden genellikle dosyada gizlenmiş tek bir sayıdır: DPI değeri.</p>\n<p>DPI, görüntü basıldığında piksellerin ne kadar yoğun paketlenmesi gerektiğini yazılıma söyler. 72 DPI olarak etiketlenmiş bir dosya bir baskı sistemine poster gibi görünürken, 300 DPI olarak etiketlenmiş aynı pikseller uygun bir sayfa gibi görünür.</p>\n<p>Bu kılavuz, CompressMyPic görüntü DPI değiştiricisinin nasıl çalıştığını, her ayarın ne anlama geldiğini ve DPI sorunlarını görüntünüzün tek bir pikseline dokunmadan nasıl düzelteceğinizi açıklar.</p>\n<h2 id=\"what-is-dpi\">DPI nedir?</h2>\n<p>DPI, inç başına nokta anlamına gelir ve bir inç kâğıda kaç basılı noktanın sığdığını tanımlar. Görüntü dosyalarında genellikle çözünürlük etiketi olarak adlandırılır ve dosya başlığında küçük bir üst veri olarak durur.</p>\n<p>300 DPI olarak etiketlenmiş 3000 piksel genişliğinde bir görüntü 10 inç genişliğinde basılır, çünkü 3000 bölü 300, 10 eder. 150 DPI olarak etiketlenmiş aynı pikseller 20 inç genişliğinde basılır; her nokta daha aralıklıdır.</p>\n<p>DPI görüntünün kendisini tanımlamaz. Görüntünün ekrandan çıkıp kâğıt, mürekkep ya da baskı makinesiyle buluştuğunda amaçlanan fiziksel boyutunu tanımlar.</p>\n<p>Çoğu kamera ve ekran görüntüsü bir DPI etiketi kaydeder ama çoğu kaydetmez. DPI etiketi olmayan bir dosya bozuk değildir; baskı boyutunu onu sonra açan programın takdirine bırakır.</p>\n<h2 id=\"dpi-is-metadata\">DPI üst veridir, piksel değildir</h2>\n<p>DPI hakkında en önemli bilgi, onu değiştirmenin görüntüyü değiştirmediğidir. Piksel ızgarası tam olarak aynı kalır ve görünür görüntü hiçbir ayrıntı kazanmaz ya da kaybetmez.</p>\n<p>DPI değiştirici, dosya başlığındaki birkaç baytı yeniden yazar ve piksel verilerini bozulmadan bırakır. Bu yüzden değişiklik kalite kaybettirmez: kaybedecek hiçbir şey yoktur, çünkü hiçbir şey yeniden kodlanmaz.</p>\n<p>Bu aynı zamanda DPI'ı değiştirmenin bulanık bir görüntüyü keskinleştiremeyeceği anlamına gelir. 300 DPI'a ayarlanmış 400'e 400 bir küçük resim yine de 400'e 400 bir küçük resimdir ve büyük basıldığında yine de yumuşak görünür.</p>\n<p>Değişikliğin yaptığı şey, sonraki programa doğru baskı boyutunu söylemektir. Bir matbaa, kitap platformu ya da dergi gönderim sistemi etiketi okur ve görüntüyü istediğiniz boyutla yerleştirir.</p>\n<h2 id=\"dpi-presets-explained\">DPI hazır ayarları açıklaması: 72'den 600'e</h2>\n<p>Araç, her biri gerçek bir durum için tasarlanmış beş hazır ayar sunar. Doğru olanı seçmek çoğunlukla görüntünün nereye gideceğini bilmekle ilgilidir.</p>\n<p>72 DPI ekran ayarıdır. İlk monitör dönemlerinden gelir ve bir dosyayı basılmak için değil, gösterilmek için tasarlanmış olarak işaretler. Birçok web görüntüsü varsayılan olarak bu etiketi taşır.</p>\n<p>96 DPI Windows ayarıdır; Windows ekranlarının standart yoğunluğudur. Çoğu ekran görüntüsünün taşıdığı etikettir ve pratikte 72 DPI ile aynı anlama gelir: bu görüntü ekranlar içindir.</p>\n<p>150 DPI deneme baskısı ayarıdır. Dahili denemeler, uzaktan görülen büyük posterler ve ince ayrıntıdan çok hızın önemli olduğu her baskı için işe yarar.</p>\n<p>300 DPI yüksek baskı ayarıdır ve en çok kullanacağınız ayardır. Kitaplar, broşürler, dergiler ve ambalajlar için standarttır ve çoğu platformun istediği değerdir. 600 DPI arşiv ayarıdır; sanat reprodüksiyonu ve büyütmeyle yakından incelenmesi gereken belgeler için kullanılır.</p>\n<h2 id=\"custom-dpi-range\">Özel DPI: 1 ile 2400 arasında herhangi bir değer</h2>\n<p>Bazen hiçbir hazır ayar uymaz. Belirli bir matbaa, dergi ya da kitap platformu alışılmadık bir değer isteyebilir ve araç 1 ile 2400 arasında herhangi bir özel DPI'ı kabul eder.</p>\n<p>İhtiyaç duyduğunuz sayıyı yazın; araç onu tam olarak uygular. Aralık bilinçli olarak geniştir, çünkü gerçek yayın akışları bazen 200, 350 ya da 1200 DPI gibi değerler ister.</p>\n<p>72'nin altındaki değerler baskı için nadiren işe yarar ama geçerli üst verilerdir. Araç sayınızı yargılamaz; onu sadık biçimde yazar ve sonucu doğrular.</p>\n<p>İşledikten sonra fikrinizi değiştirirseniz aynı dosyalara başka bir DPI uygulayabilirsiniz. Araç, işlenmiş görüntüleri 300 DPI geçişinden sonra 600 DPI'a yeniden geçirmenize izin verir; iki adımda da kalite kaybı olmaz.</p>\n<h2 id=\"jpeg-and-png-only\">Hangi biçimler çalışır: JPEG ve PNG</h2>\n<p>DPI değiştirici JPEG ve PNG dosyalarıyla çalışır, çünkü bu biçimler DPI etiketini standart bir yerde saklar. İkisi de piksel verilerini yeniden kodlamadan, kalite kaybı olmadan işlenir.</p>\n<p>Diğer biçimler net bir mesajla reddedilir. WebP, HEIC, BMP, GIF ve SVG dosyaları DPI etiketini aynı biçimde taşımaz; bu yüzden onlara etiket koymak yanıltıcı olur.</p>\n<p>Dosyanız WebP ise önce JPG ya da PNG'ye dönüştürün, sonra DPI'ı ayarlayın. <a href=\"/tr/gorsel-donustur\">Görüntü dönüştürücü</a> bu adımı üstlenir ve DPI değiştirici oradan devam eder.</p>\n<p>Bu sınır bir özellik, bir eksiklik değildir. DPI'ı saklayamayan bir biçimde DPI ayarlıyormuş gibi yapan bir araç, sessizce platform denetiminden yine de geçemeyen dosyalar üretirdi.</p>\n<h2 id=\"before-not-set\">Fotoğraflar neden Önce: Tanımlanmamış gösterir?</h2>\n<p>Yüklenen birçok fotoğraf araçta Önce: Tanımlanmamış gösterir; bu insanları şaşırtır. Fotoğraf iyidir; yalnızca başlığında kayıtlı hiçbir DPI etiketi yoktur.</p>\n<p>Telefon kameraları DPI etiketini sık sık tamamen atlar, çünkü telefon fotoğrafın basılıp basılmayacağını ya da ekranda paylaşılıp paylaşılmayacağını bilmez. Ekran görüntüleri de aynı davranır.</p>\n<p>Eksik bir etiket hata değildir ama isteyen platformlar için sorundur. Amazon KDP, akademik dergiler ve matbaalar DPI değerini denetler ve eksik bir değer arıza sayılır.</p>\n<p>O dosyada DPI ayarlamak eksik üst verileri tamamlar. Pikseller değişmez ama dosya artık platformun sorusunu boş bırakmak yerine yanıtlar.</p>\n<h2 id=\"verified-dpi-badge\">Doğrulanmış DPI rozeti</h2>\n<p>İşledikten sonra her dosya Doğrulanmış DPI rozeti alır. Rozet süs değildir; aracın dosyayı yeniden okuyup yeni DPI değerinin gerçekten içinde kayıtlı olduğunu doğruladığı anlamına gelir.</p>\n<p>Doğrulama önemlidir, çünkü DPI etiketleri yanıltıcı olabilir. Bazı biçimler değeri inç başına nokta yerine santimetre başına nokta olarak saklar ve dikkatsiz bir araç birini yazarken okuyucu diğerini bekleyebilir.</p>\n<p>Değiştirici bu dönüşümü doğru işler ve sonra sonucu okuyarak kanıtlar. Rozet görünüyorsa dosya, standarda uyan her okuyucuda aynı DPI'ı bildirir.</p>\n<p>Bir dosya göndermeden önce rozeti arayın. Doğrulanmamış, işlenmiş bir dosya bir varsayımdır ve yayın platformları varsayımları kabul etmez.</p>\n<h2 id=\"exif-and-icc-preservation\">EXIF etiketleri ve ICC profilleri korunur</h2>\n<p>DPI'ı değiştirmek yalnızca başlıktaki çözünürlük baytlarını yeniden yazar. Tarih, kamera modeli ve pozlama ayarları dahil kameranızın EXIF verileri tam olarak olduğu gibi kalır.</p>\n<p>ICC renk profili de korunur. Bu profil yazıcılara ve ekranlara renkleri nasıl yorumlayacaklarını söyler ve onu kaybetmek görüntünün her rengini değiştirirdi.</p>\n<p>Bu yüzden araç profesyonel işler için güvenlidir. Bir fotoğrafçı, müşterinin ihtiyaç duyduğu üst verilerin silindiğinden endişe etmeden bir müşteri dosyasında DPI ayarlayabilir.</p>\n<p>Üst verileri gerçekten silmek istiyorsanız o ayrı bir iştir. <a href=\"/tr/gorsel-metadata-kaldir\">Görüntü üst verilerini kaldırma aracı</a> EXIF ve konum verilerini kaldırırken, DPI değiştirici onları bilinçli olarak bozulmadan tutar.</p>\n<h2 id=\"png-299-vs-300\">Bir PNG neden bazen 299 DPI olarak okunur?</h2>\n<p>Bazı kullanıcılar bir PNG'de 300 DPI ayarlar ve başka bir programda 299 DPI olarak okur. Bu bir hata gibi görünür ama PNG'nin çözünürlüğü saklama biçiminden kaynaklanan bir yuvarlama etkisidir.</p>\n<p>PNG dosyaları çözünürlüğü inç başına piksel olarak değil, metre başına piksel olarak saklar. 300 DPI'ı metre başına piksele dönüştürmek tam bölünmeyen bir sayı verir; bu yüzden kayıtlı değer hafifçe yuvarlanır.</p>\n<p>Bir okuyucu onu DPI'a geri dönüştürdüğünde sonuç 300 yerine 299 olabilir. Fark üç yüzde bir nokta farktır ve hiçbir baskıda görünür bir etkisi yoktur.</p>\n<p>Çoğu platform 299 DPI'ı 300'e eşdeğer kabul eder ama sizinki katıysa o dosya için JPEG kullanın. JPEG DPI'ı doğrudan inç başına nokta olarak saklar; bu yüzden tam olarak 300 olarak okunur.</p>\n<h2 id=\"batch-zip-workflow\">Toplu işleme ve ZIP dışa aktarma</h2>\n<p>Baskı projeleri nadiren tek bir görüntü içerir. Bir kitap bölümü, ürün kataloğu ya da dergi yazısı 300 DPI olarak işaretlenmesi gereken onlarca görüntü isteyebilir ve bunları tek tek yapmak sıkıcıdır.</p>\n<p>DPI değiştirici dosyaları toplu işler. Tüm seti bırakın, ayarı bir kez seçin ve her dosya tek geçişte aynı DPI değerini alır.</p>\n<p>Grup bittiğinde tüm sonuçları tek bir ZIP dosyası olarak indirin. ZIP, tek tek dosya adlarını korur; bu yüzden görüntüler doğrudan çıktıkları proje klasörüne döner.</p>\n<p>Yalnızca birkaçına ihtiyacınız varsa dosyaları tek tek de indirebilirsiniz. Toplu akış hacim içindir; tek tek indirme hızlı bir görüntüyü düzeltmek içindir.</p>\n<h2 id=\"dpi-and-file-size\">DPI'ı değiştirmek dosya boyutunu değiştirir mi?</h2>\n<p>Hayır ya da neredeyse hiç. DPI etiketi başlıkta birkaç bayttır; bu yüzden onu değiştirmek dosya boyutuna ölçülebilir hiçbir şey eklemez ya da çıkarmaz.</p>\n<p>Değişiklikten önce 2,4 MB ağırlığında olan bir JPEG sonrasında da 2,4 MB ağırlığındadır. Piksellere dokunulmaz, sıkıştırmaya dokunulmaz ve yalnızca üst veriler farklıdır.</p>\n<p>Bu, 300 DPI'lık bir dosyanın 72 DPI'lık bir dosyadan daha büyük olmasını bekleyenleri şaşırtır. Dosya boyutu piksellerden ve sıkıştırmadan gelir, DPI etiketinden değil ve etiket neredeyse ücretsizdir.</p>\n<p>Bir dosyanın gerçekten daha küçük olması gerekiyorsa ayrı olarak sıkıştırın. <a href=\"/tr/\">Görüntü sıkıştırıcı</a>, boyutları değiştirmeden ağırlığı azaltır ve sonra DPI değiştirici daha küçük dosyada baskı etiketini ayarlayabilir.</p>\n<h2 id=\"why-platforms-reject-72-dpi\">Platformlar 72 DPI dosyaları neden reddeder?</h2>\n<p>Yayın platformları 72 DPI dosyaları reddeder, çünkü etiket onlara görüntünün ekranlar için olduğunu söyler. 72 DPI gören bir kitap matbaası, görüntünün çok büyük ve çok yumuşak basılacağını varsayar.</p>\n<p>Amazon KDP, akademik dergiler ve stok fotoğraf siteleri bu nedenle minimum DPI kuralları uygular. Titiz davranmıyorlar; basılı sonucu koruyorlar.</p>\n<p>Çözüm, anladıktan sonra hızlıdır. Dosyayı 300 DPI olarak işaretleyin, rozeti doğrulayın ve yeniden gönderin. Pikseller her zaman yeterince iyiydi; yalnızca üst veriler yanlıştı.</p>\n<p>Sınırı hatırlayın ama. Pikseller baskı boyutu için gerçekten çok azsa hiçbir DPI değeri dosyayı kurtaramaz. Önce boyutları <a href=\"/tr/gorsel-boyut-olcer\">görüntü boyut denetleyici</a> ile inceleyin.</p>\n<h2 id=\"re-applying-dpi\">Sonra farklı bir DPI uygulama</h2>\n<p>İş akışları değişir ve 300 DPI olarak işaretlenmiş bir dosya sonra arşiv baskısı için 600 DPI isteyebilir. Araç, dosyaları istediğiniz kadar yeniden işlemenize izin verir.</p>\n<p>Her geçiş kalite kaybettirmez; bu yüzden yeniden işaretlemek kalite açısından hiçbir şeye mal olmaz. Başlık yeniden yazılır, pikseller bozulmadan kalır ve yeni değer yeni bir rozetle doğrulanır.</p>\n<p>Bu, aynı kaynak dosyalarla hem baskıya hem arşive hizmet veren ekipler için yararlıdır. Bir piksel kümesi kitap için 300 DPI ve arşiv için 600 DPI taşıyabilir; kopyalama olmadan.</p>\n<p>Yine de orijinal dosyaları güvende tutun. Bir DPI değişikliği geri alınabilir ama orijinalin bozulmadan olması, neyin ne zaman değiştirildiğini asla merak etmeniz gerekmediği anlamına gelir.</p>\n<h2 id=\"how-to-use-the-tool\">Görüntü DPI değiştirici nasıl kullanılır?</h2>\n<p><a href=\"/tr/gorsel-dpi-degistir\">Görüntü DPI değiştirici</a> aracını açın ve JPEG ya da PNG dosyalarınızı yükleme alanına bırakın. Bir yakalamayı saniyeler içinde 300 DPI olarak işaretlemek için panodan doğrudan da yapıştırabilirsiniz.</p>\n<p>Bir hazır ayar seçin ya da 1 ile 2400 arasında özel bir değer yazın. Araç her dosyanın mevcut DPI'ını gösterir ya da dosyanın hiç etiketi yoksa Tanımlanmamış gösterir.</p>\n<p>Dosyaları işleyin ve her sonuçta Doğrulanmış DPI rozetini arayın. Ayrı ayrı ya da tek bir ZIP olarak indirin, sonra değeri yayın platformunuzda doğrulayın.</p>\n<p>Adım adım sürüm için <a href=\"/tr/blog/gorsel-dpi-nasil-degistirilir\">Görüntü DPI'ı Nasıl Değiştirilir?</a> yazısını okuyun ve sayıların ardındaki teori için <a href=\"/tr/blog/dpi-vs-ppi-baski-web\">DPI ve PPI: Baskı ve Web İçin Ne Önemlidir?</a> yazısına bakın.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"DPI'ı değiştirmek görüntümü ekranda daha keskin gösterir mi?","answer":"Hayır. DPI baskı üst verisidir ve tarayıcılar onu görmezden gelir; bu yüzden görüntü değişiklikten önce ve sonra ekranda tam olarak aynı görünür. Ekrandaki keskinlik piksel boyutlarından gelir, DPI etiketinden değil. Görüntü ekranda yumuşak görünüyorsa daha fazla piksele ihtiyaç duyar, daha yüksek bir DPI'a değil."},{"question":"Bu araçla bir WebP ya da HEIC dosyasında DPI ayarlayabilir miyim?","answer":"Hayır. Araç yalnızca JPEG ve PNG ile çalışır, çünkü bu biçimler DPI etiketini standart biçimde saklar. Önce bir WebP ya da HEIC dosyasını görüntü dönüştürücüyle JPG ya da PNG'ye dönüştürün, sonra dönüştürülen dosyada DPI ayarlayın."},{"question":"Kitap kapağı ya da dergi sayfası için hangi DPI'ı kullanmalıyım?","answer":"300 DPI, kitaplar, dergiler, broşürler ve ambalajlar için standarttır. 300 DPI ayarını kullanın ve piksel boyutlarının fiziksel boyut için yeterince büyük olduğunu doğrulayın. Sanat ya da arşiv reprodüksiyonu için 600 DPI ayarına yükselin."},{"question":"DPI değiştirici telefonumda çalışır mı?","answer":"Evet. Araç iOS ve Android mobil tarayıcılarda çalışır. Galerinize JPEG ya da PNG dosyaları yükleyin, bir hazır ayar seçin ve işaretlenmiş dosyaları indirin. Toplu ZIP indirmeleri cep telefonunda da çalışır."},{"question":"PNG'm 300 DPI ayarladıktan sonra neden 299 DPI okuyor?","answer":"PNG çözünürlüğü metre başına piksel olarak saklar ve 300 DPI'ı bu birime dönüştürmek hafifçe yuvarlanır. Başka bir program onu geri dönüştürdüğünde 299 DPI okuyabilir. Fark baskıda görünmez ve çoğu platform onu kabul eder. Tam 300 okuması için JPEG kullanın."},{"question":"Hesap ya da ödeme olmadan DPI değiştirebilir miyim?","answer":"Evet. Araç ücretsizdir, hesap istemez ve her şeyi tarayıcınızda yerel olarak işler. Kaç dosya işaretleyeceğinizin sınırı yoktur ve görüntüleriniz asla bir sunucuya yüklenmez."}];
